*** Add File: scripts/reorder_evidence_page.mjs
+import { readFileSync, writeFileSync } from "node:fs";
+
+const evidencePath = new URL("../firebase/public/evidence.html", import.meta.url);
+const source = readFileSync(evidencePath, "utf8");
+
+const storyMarker = "<!-- ==================== STORY PIPELINE: CROSS-MODEL ==================== -->";
+const precursorMarker = "<!-- ==================== LEGACY PERTURBATION PIPELINE ==================== -->";
+const closingMarker = '<div style="text-align:center;margin-top:1rem"><a href="methodology.html" class="cta-btn">';
+
+const storyStart = source.indexOf(storyMarker);
+const precursorStart = source.indexOf(precursorMarker);
+const closingStart = source.indexOf(closingMarker);
+
+if (storyStart < 0 || precursorStart < 0 || closingStart < 0) {
+  throw new Error("Evidence-page boundary marker missing; refusing to rewrite the page.");
+}
+if (!(storyStart < precursorStart && precursorStart < closingStart)) {
+  throw new Error("Evidence-page blocks are not in the expected pre-restructure order.");
+}
+
+const beforeStory = source.slice(0, storyStart);
+const storyCorpus = source.slice(storyStart, precursorStart);
+const precursorCorpus = source.slice(precursorStart, closingStart);
+const closing = source.slice(closingStart);
+
+const bridge = `<!-- The bridge names the methodological inheritance between the two independent corpora. -->
+<section class="sec narrative-step bridge-step">
+<div class="circle-label">WHY THE INSTRUMENT CHANGED</div>
+<h2 id="precursor-bridge">Bridge: What the Precursor Made Possible</h2>
+<p class="lead"><strong>The precursor found the signals; the story instrument followed them through time.</strong> The archived runs showed how to perturb a specification and measure Grit, basin escape, recovery, flailing, and strategy in one session. They could not show whether those effects survived the handoff into the next task. The current instrument reuses those operators and recovery signals across five linked sessions, where each model inherits the code and context produced before it.</p>
+</section>
+
+`;
+
+writeFileSync(evidencePath, beforeStory + precursorCorpus + bridge + storyCorpus + closing);
*** End Patch

