+
+my $story_start = index $source, $story_marker;
+my $precursor_start = index $source, $precursor_marker;
+my $closing_start = index $source, $closing_marker;
+
+die "Evidence-page boundary marker missing; refusing to rewrite the page.\n"
+    if $story_start < 0 || $precursor_start < 0 || $closing_start < 0;
+die "Evidence-page blocks are not in the expected pre-restructure order.\n"
+    unless $story_start < $precursor_start && $precursor_start < $closing_start;
+
+my $before_story = substr $source, 0, $story_start;
+my $story_corpus = substr $source, $story_start, $precursor_start - $story_start;
+my $precursor_corpus = substr $source, $precursor_start, $closing_start - $precursor_start;
+my $closing = substr $source, $closing_start;
